previewCss:
.darma-loader-darma-b14-baton-pass { --accent: var(--loader-color, #f97316); --accent-2: var(--loader-secondary-color, #1d4ed8); width: var(--loader-size, 128px); height: calc(var(--loader-size, 128px) * .42); position: relative; }
.darma-loader-darma-b14-baton-pass::after { content: ''; position: absolute; bottom: 16%; left: 0; width: 100%; height: 8%; border-radius: 999px; background: color-mix(in srgb, #000 18%, var(--accent-2)); }
.darma-loader-darma-b14-baton-pass span { position: absolute; bottom: 10%; width: 14%; height: 54%; border-radius: 40% 40% 7px 7px; background: linear-gradient(var(--accent-2), color-mix(in srgb, #000 26%, var(--accent-2))); animation: darma-loader-darma-b14-baton-pass-handoff calc(var(--loader-speed, 1s) * 3) ease-in-out infinite; }
.darma-loader-darma-b14-baton-pass span::after { content: ''; position: absolute; bottom: 96%; left: 14%; width: 72%; height: calc(var(--loader-size, 128px) * .075); border-radius: 50%; background: color-mix(in srgb, #fff 16%, var(--accent-2)); }
.darma-loader-darma-b14-baton-pass span:nth-child(1) { left: 3%; }
.darma-loader-darma-b14-baton-pass span:nth-child(2) { left: 43%; animation-delay: calc(var(--loader-speed, 1s) * .9); }
.darma-loader-darma-b14-baton-pass span:nth-child(3) { left: 83%; animation-delay: calc(var(--loader-speed, 1s) * 1.8); }
.darma-loader-darma-b14-baton-pass .darma-loader-darma-b14-baton-pass__baton { position: absolute; bottom: 40%; width: 20%; height: 13%; border-radius: 999px; background: linear-gradient(90deg, var(--accent), color-mix(in srgb, #fff 42%, var(--accent))); animation: darma-loader-darma-b14-baton-pass-pass calc(var(--loader-speed, 1s) * 3) ease-in-out infinite; }
@keyframes darma-loader-darma-b14-baton-pass-pass { 0%, 8% { left: 4%; } 30%, 38% { left: 44%; } 60%, 68% { left: 82%; } 92%, 100% { left: 4%; } }
@keyframes darma-loader-darma-b14-baton-pass-handoff { 0%, 14% { transform: scaleY(1); filter: brightness(1); } 22% { transform: scaleY(1.14); filter: brightness(1.4); } 34%, 100% { transform: scaleY(1); filter: brightness(1); } }

